const TRIGGERS = ['Lich giao dich', 'Lich ngoai gio', 'Chay tay'];
const trigger = TRIGGERS.find((n) => {
  try {
    return $(n).isExecuted;
  } catch (e) {
    return false;
  }
}) ?? '';

return [{
  json: {
    trigger,
    run_started_at: DateTime.now().setZone('Asia/Ho_Chi_Minh').toISO({ suppressMilliseconds: true }),
    sources: SOURCES,
    watchlist: WATCHLIST,
    MAX_ITEMS_PER_RUN: 300,
    MAX_AI_ITEMS_PER_DAY: 200,
    // Phan han muc AI toi da cho tin chi vi nguon tier 1 (khong khop watchlist/vi mo).
    TIER1_ONLY_AI_SHARE: 0.5,
    ALERT_MIN_IMPORTANCE: 4,
    AI_BATCH_SIZE: 10,
    SNIPPET_MAX_CHARS: 500,
    DRY_RUN: true,
    // Chi dung khi kiem thu: tai feed tu may chu tep cuc bo thay cho URL that.
    FEED_BASE_OVERRIDE: "",
  },
}];

// Tach danh sach nguon thanh mot item cho moi nguon.
const cfg = $input.first().json;
return cfg.sources.map((s) => ({
  json: {
    id: s.id,
    name: s.name,
    tier: s.tier,
    lang: s.lang,
    url: cfg.FEED_BASE_OVERRIDE ? `${cfg.FEED_BASE_OVERRIDE}${s.id}.xml` : s.url,
  },
}));

// Gan ma nguon vao chinh van ban XML, vi node XML khong giu lien ket voi item dau vao.
// Bo BOM o dau feed (hai feed tieng Anh co BOM, giai doan 1).
const src = $('Tach nguon').item.json;
let xml = String($json.data ?? '').replace(/^﻿/, '');
const tag = `<n8n_source_id>${src.id}</n8n_source_id>`;
if (/<channel[^>]*>/.test(xml)) {
  xml = xml.replace(/<channel([^>]*)>/, `<channel$1>${tag}`);
}
return { json: { data: xml, source_id: src.id } };

// Ghi lai nguon tai loi. Cac nguon khac van chay tiep.
const src = $('Tach nguon').item.json;
const err = $json.error;
const message = typeof err === 'string' ? err : (err?.message ?? JSON.stringify(err ?? $json));
return { json: { source_id: src.id, error: String(message).slice(0, 300) } };

// Chuan hoa tin: URL, ngay gio ICT, doan trich; loai trung trong cung lan chay theo URL chuan hoa.
const cfg = $('Config').first().json;
const sources = Object.fromEntries(cfg.sources.map((s) => [s.id, s]));
const TZ = 'Asia/Ho_Chi_Minh';
const fetchedAt = DateTime.now().setZone(TZ).toISO({ suppressMilliseconds: true });
const TRACKING = /^(utm_.*|fbclid|gclid|zarsrc|ref|source)$/i;

const asText = (v) => {
  if (v === undefined || v === null) return '';
  if (Array.isArray(v)) return asText(v[0]);
  if (typeof v === 'object') return String(v._ ?? '');
  return String(v);
};
const decodeEntities = (s) =>
  s
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&amp;/g, '&');
const plain = (s) => decodeEntities(s.replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();

// Khong dung lop URL: moi truong chay Code node khong co san (da thay o lan chay thu dau tien).
function cleanUrl(raw) {
  const m = raw.trim().match(/^https?:\/\/([^/?#\s]+)([^?#\s]*)(\?[^#\s]*)?/i);
  if (!m) return null;
  const keep = (m[3] ?? '')
    .slice(1)
    .split('&')
    .filter((p) => p && !TRACKING.test(p.split('=')[0]));
  return `https://${m[1]}${m[2] || '/'}${keep.length ? `?${keep.join('&')}` : ''}`;
}
function canonicalUrl(clean) {
  return clean
    .replace(/^https:\/\/([^/?#]+)/, (_, host) => `https://${host.toLowerCase().replace(/^www\./, '')}`)
    .replace(/\/$/, '');
}
function toIct(raw) {
  if (!raw) return null;
  let d = DateTime.fromRFC2822(raw.trim());
  if (!d.isValid) {
    const js = new Date(raw);
    if (!Number.isNaN(js.getTime())) d = DateTime.fromJSDate(js);
  }
  return d.isValid ? d.setZone(TZ).toISO({ suppressMilliseconds: true }) : null;
}

const seen = new Map();
for (const item of $input.all()) {
  const channel = item.json?.rss?.channel;
  if (!channel) continue; // loi phan tich XML: dem o buoc Tong ket
  const src = sources[asText(channel.n8n_source_id)];
  if (!src) continue;
  const entries = Array.isArray(channel.item) ? channel.item : channel.item ? [channel.item] : [];
  for (const e of entries) {
    const url = cleanUrl(asText(e.link) || asText(e.guid));
    const title = plain(asText(e.title));
    if (!url || !title) continue;
    const canonical = canonicalUrl(url);
    if (seen.has(canonical)) continue;
    seen.set(canonical, {
      source_id: src.id,
      source_name: src.name,
      source_tier: src.tier,
      lang: src.lang,
      title,
      url,
      url_canonical: canonical,
      snippet: plain(asText(e.description)).slice(0, cfg.SNIPPET_MAX_CHARS),
      published_at: toIct(asText(e.pubDate)),
      fetched_at: fetchedAt,
    });
  }
}

const rows = [...seen.values()].sort((a, b) => (b.published_at ?? '').localeCompare(a.published_at ?? ''));
return rows.map((json) => ({ json }));

// Khop watchlist va chu de vi mo theo docs/DESIGN.md muc 4.
const wl = $('Config').first().json.watchlist;
const strip = (s) =>
  s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const B = '(^|[^\\p{L}\\p{N}])';
const E = '($|[^\\p{L}\\p{N}])';
const phrase = (p, flags) => new RegExp(`${B}${escapeRe(p)}${E}`, flags);
const hasDiacritics = (s) => strip(s) !== s;

const tickers = (wl.tickers ?? []).map((t) => ({
  ...t,
  re: new RegExp(`(^|[^A-Za-z0-9])${escapeRe(t.ticker)}($|[^A-Za-z0-9])`, 'u'),
  context: new RegExp(`(\\(${escapeRe(t.ticker)}\\)|(mã|cổ phiếu|CP|ticker)\\s*:?\\s*${escapeRe(t.ticker)}(?![A-Za-z0-9]))`, 'iu'),
  aliases: (t.aliases ?? []).filter((a) => a.length >= 4).map((a) => ({
    alias: a,
    re: phrase(a.normalize('NFC').toLowerCase(), 'u'),
    reStripped: phrase(strip(a).toLowerCase(), 'u'),
  })),
}));
const topics = (wl.macro_topics ?? []).map((t) => ({
  topic: t,
  re: phrase(t.normalize('NFC').toLowerCase(), 'u'),
  reStripped: phrase(strip(t).toLowerCase(), 'u'),
}));
const excludes = (wl.exclude_keywords ?? []).map((k) => phrase(k.normalize('NFC').toLowerCase(), 'u'));

return $input.all().map((item) => {
  const raw = `${item.json.title} ${item.json.snippet}`.normalize('NFC');
  const lower = raw.toLowerCase();
  const lowerStripped = strip(lower);
  const accented = hasDiacritics(raw);
  const foundTickers = [];
  const reasons = [];

  for (const t of tickers) {
    const aliasHit = t.aliases.find((a) => a.re.test(lower) || a.reStripped.test(lowerStripped));
    const codeHit = t.re.test(raw) && (!t.ambiguous || t.context.test(raw) || aliasHit);
    if (codeHit || aliasHit) {
      foundTickers.push(t.ticker);
      reasons.push(codeHit ? `ticker:${t.ticker}` : `alias:${aliasHit.alias}`);
    }
  }
  const foundTopics = [];
  for (const t of topics) {
    // Khop ban co dau truoc; ban khong dau chi dung khi tin viet khong dau.
    if (t.re.test(lower) || (!accented && t.reStripped.test(lowerStripped))) {
      foundTopics.push(t.topic);
      reasons.push(`topic:${t.topic}`);
    }
  }
  const excluded = excludes.some((re) => re.test(lower));
  if (excluded) reasons.push('excluded');

  return {
    json: {
      ...item.json,
      tickers: foundTickers.join(','),
      topics: foundTopics.join(','),
      match_reason: reasons.join(';'),
      excluded,
    },
  };
});

// Dua item ve dung cac cot cua bang news_items (Data Table tu choi cot la).
// Tin khop watchlist/vi mo hoac nguon tier 1 duoc danh dau pending_ai; nhanh AI phan loai tiep.
const runId = String($execution.id);
return $input.all().map(({ json: j }) => {
  const forAi = !j.excluded && (j.tickers !== '' || j.topics !== '' || j.source_tier === 1);
  return {
    json: {
      item_id: j.item_id,
      source_id: j.source_id,
      source_name: j.source_name,
      source_tier: j.source_tier,
      lang: j.lang,
      title: j.title,
      url: j.url,
      snippet: j.snippet,
      published_at: j.published_at,
      fetched_at: j.fetched_at,
      tickers: j.tickers,
      topics: j.topics,
      match_reason: j.match_reason,
      event_type: '',
      fact_or_opinion: '',
      importance: j.excluded ? 1 : null,
      sentiment: '',
      summary_vi: '',
      why_it_matters: '',
      needs_human_check: false,
      classified_by: j.excluded ? 'excluded' : forAi ? 'pending_ai' : 'not_matched',
      alert_sent_at: null,
      run_id: runId,
    },
  };
});

// Chon tin vao AI trong han muc ngay (MAX_AI_ITEMS_PER_DAY, dem theo ngay ICT trong ai_usage).
// Tin khop watchlist/vi mo duoc uu tien. Tin chi vi nguon tier 1 chi vao AI khi tong da dung
// trong ngay < TIER1_ONLY_AI_SHARE * han muc, nen tin khop luon con it nhat phan con lai.
// Tin vuot han muc chuyen sang keyword_only: van luu, khong goi AI.
const cfg = $('Config').first().json;
const today = DateTime.now().setZone('Asia/Ho_Chi_Minh').toFormat('yyyy-MM-dd');
const usage = $input.all().map((i) => i.json).find((u) => u.date === today) ?? {};
const cap = Number(cfg.MAX_AI_ITEMS_PER_DAY) || 0;
const tier1Cap = Math.floor(cap * (Number(cfg.TIER1_ONLY_AI_SHARE) || 0));
let used = Number(usage.items) || 0;

const rows = $('Dinh dang dong').all().map(({ json }) => ({ ...json }));
const isMatched = (r) => r.tickers !== '' || r.topics !== '';
const pending = rows.filter((r) => r.classified_by === 'pending_ai');
for (const r of [...pending.filter(isMatched), ...pending.filter((x) => !isMatched(x))]) {
  const limit = isMatched(r) ? cap : tier1Cap;
  if (used < limit) {
    used += 1;
  } else {
    r.classified_by = 'keyword_only';
    r.needs_human_check = true;
  }
}
return rows.map((json) => ({ json }));

// Gom tin can AI thanh lo AI_BATCH_SIZE tin, dung van ban dau vao theo DESIGN 5.2.
// Noi dung tin duoc thay < > " de tin khong the dong the gia.
let cfg = {};
try {
  cfg = $('Config').first().json;
} catch (e) {
  // Workflow danh gia khong co node Config: dung mac dinh.
}
const size = Number(cfg.AI_BATCH_SIZE) || 10;
const typeOf = Object.fromEntries((cfg.sources ?? []).map((s) => [s.id, s.type]));
const esc = (s) => String(s ?? '').replace(/</g, '‹').replace(/>/g, '›').replace(/"/g, '”');
const HEADER = 'Mã và chủ đề trong watchlist đã khớp được ghi ở từng tin. Phân loại các tin sau.';

const rows = $input.all().map((i) => i.json);
const out = [];
for (let b = 0; b < rows.length; b += size) {
  const batch = rows.slice(b, b + size);
  // id ngan 6 ky tu; neu trung trong lo thi keo dai.
  let len = 6;
  while (new Set(batch.map((r) => String(r.item_id).slice(0, len))).size < batch.length) len += 2;
  const ids = batch.map((r) => String(r.item_id).slice(0, len));
  const parts = batch.map((r, k) => {
    const khop = [r.tickers && `ticker:${r.tickers}`, r.topics && `chu_de:${r.topics}`]
      .filter(Boolean).join(';') || 'khong';
    const loai = r.source_type ?? typeOf[r.source_id] ?? 'press';
    return `<tin id="${ids[k]}" nguon="${esc(r.source_id)}" loai_nguon="${esc(loai)}" khop="${esc(khop)}">\n`
      + `<tieu_de>${esc(r.title)}</tieu_de>\n<trich_doan>${esc(r.snippet)}</trich_doan>\n</tin>`;
  });
  out.push({ json: { batch_no: out.length + 1, ids, rows: batch, text: `${HEADER}\n\n${parts.join('\n')}` } });
}
return out;

